"""Unit tests for matrix_rings.py."""

from __future__ import annotations

import itertools

import galois
import numpy as np
import pytest

from qldpc import abstract


def test_construction() -> None:
    """A ring generated by a cyclic shift is isomorphic to the algebra of a cyclic group."""
    shift = np.roll(np.eye(3, dtype=int), 1, axis=0)
    ring = abstract.MatrixRing(shift)
    assert ring.field is galois.GF2
    assert ring.dim == ring.lift_dim == 3

    # the basis is the identity followed by powers of the generator
    (generator,) = ring.generators
    for power, member in enumerate(ring.basis):
        assert np.array_equal(member.lift(), np.linalg.matrix_power(shift, power))
    assert generator**3 == ring.one

    # rings are equal if they have the same field and basis
    assert ring == abstract.MatrixRing(shift) and hash(ring) == hash(abstract.MatrixRing(shift))
    assert ring != abstract.MatrixRing(shift, field=4)
    larger_ring = abstract.MatrixRing(shift, shift[::-1])
    assert larger_ring.dim > ring.dim and ring != larger_ring
    assert ring != abstract.GroupRing(abstract.CyclicGroup(3))
    assert ring != abstract.MatrixRing(shift @ shift)  # the same members, in another basis

    # generators are the given matrices, including repeats
    swap = np.array([[0, 1], [1, 0]])
    generators = abstract.MatrixRing(swap, swap).generators
    assert len(generators) == 2 and all(np.array_equal(gen.lift(), swap) for gen in generators)

    # a field is inferred from generators that are field arrays
    field = galois.GF(4)
    assert abstract.MatrixRing(field(shift)).field is field


def test_invalid_construction() -> None:
    """Generators must be square matrices of one size over one field."""
    with pytest.raises(ValueError, match="at least one"):
        abstract.MatrixRing()
    with pytest.raises(ValueError, match="square matrices of one size"):
        abstract.MatrixRing(np.ones(2, dtype=int))
    with pytest.raises(ValueError, match="square matrices of one size"):
        abstract.MatrixRing(np.ones((2, 3), dtype=int))
    with pytest.raises(ValueError, match="square matrices of one size"):
        abstract.MatrixRing(np.eye(2, dtype=int), np.eye(3, dtype=int))
    with pytest.raises(ValueError, match="square matrices of one size"):
        abstract.MatrixRing(np.zeros((0, 0), dtype=int))
    with pytest.raises(ValueError, match="must be over GF"):
        abstract.MatrixRing(galois.GF(4).Identity(2), field=2)


@pytest.mark.parametrize(
    "group,field", [(abstract.DihedralGroup(3), 3), (abstract.CyclicGroup(3), 4)]
)
def test_agreement_with_group_ring(
    group: abstract.Group, field: int, pytestconfig: pytest.Config
) -> None:
    """A ring generated by the regular representation of a group matches its group algebra."""
    group_ring = abstract.GroupRing(group, field)
    ring = abstract.MatrixRing(*[group_ring.regular_lift(member) for member in group.generators])
    assert ring.field is group_ring.field and ring.dim == group_ring.dim
    assert ring.is_commutative == group_ring.is_commutative
    assert ring.has_involution

    def from_group_ring(member: abstract.RingMember) -> abstract.RingMember:
        return ring.member_from_matrix(member.regular_lift())

    # multiplication respects coefficients that are not one, in the field of the ring
    scalar = ring.field.primitive_element
    first, last = ring.generators[0], ring.generators[-1]
    member_x, member_y = first * scalar + last, first + last * scalar
    assert np.array_equal((member_x * member_y).lift(), member_x.lift() @ member_y.lift())
    assert np.array_equal(
        (member_x * member_y).lift(right=True),
        member_y.lift(right=True) @ member_x.lift(right=True),
    )

    # products of generators, in both orders, agree with those in the group algebra
    for (aa, gg_a), (bb, gg_b) in itertools.product(
        zip(ring.generators, group_ring.generators), repeat=2
    ):
        assert np.array_equal((aa * bb).lift(), (gg_a * gg_b).regular_lift())
        assert np.array_equal(aa.T.lift(), gg_a.T.regular_lift())

        # regular lifts act on coefficient vectors like multiplication from the left or right
        assert np.array_equal(aa.regular_lift() @ bb.to_vector(), (aa * bb).to_vector())
        assert np.array_equal(aa.regular_lift(right=True) @ bb.to_vector(), (bb * aa).to_vector())

        # lifts to opposite rings are anti-representations
        assert np.array_equal((aa * bb).lift(right=True), bb.lift(right=True) @ aa.lift(right=True))

    # random members add like those of the group algebra, and transpose like their lifts
    seed = pytestconfig.getoption("randomly_seed")
    vectors = group_ring.field.Random((2, group_ring.dim), seed=seed)
    members = [abstract.RingMember.from_vector(vector, group_ring) for vector in vectors]
    member_a, member_b = (from_group_ring(member) for member in members)
    assert np.array_equal((member_a + member_b).lift(), (members[0] + members[1]).regular_lift())
    assert np.array_equal(member_a.T.lift(), member_a.lift().T)


def test_matrix_units() -> None:
    """The ring of 2x2 matrices is generated by two matrix units that transpose into each other."""
    upper = np.array([[0, 1], [0, 0]])
    lower = upper.T
    ring = abstract.MatrixRing(upper, lower, field=3)
    assert ring.dim == 4 and ring.has_involution
    assert not ring.is_commutative and not ring.is_abelian
    unit_upper, unit_lower = ring.generators
    assert unit_upper.T == unit_lower and unit_upper * unit_lower != unit_lower * unit_upper
    assert np.array_equal((unit_upper * unit_lower).lift(), [[1, 0], [0, 0]])

    # ``upper @ lower`` is the fourth basis element, found before ``lower @ upper`` because the
    # search appends generators on the right
    assert np.array_equal(ring.basis[3].lift(), upper @ lower)

    assert unit_upper.inverse() is None
    assert (ring.one + unit_upper).inverse() == ring.one - unit_upper


def test_involution() -> None:
    """``RingMember.T`` is the matrix transpose, if the ring is closed under transposition."""
    ring = abstract.MatrixRing(np.array([[1, 1], [2, 1]]), field=3)
    (generator,) = ring.generators
    assert ring.dim == 2 and ring.has_involution
    assert np.array_equal(generator.T.lift(), generator.lift().T)

    ring = abstract.MatrixRing(np.array([[0, 0], [1, 0]]))
    assert ring.dim == 2 and not ring.has_involution
    with pytest.raises(ValueError, match="no involution"):
        _ = ring.generators[0].T


def test_member_from_matrix() -> None:
    """Ring members are in correspondence with the matrices in a ring."""
    ring = abstract.MatrixRing(np.array([[0, 1], [1, 0]]))
    one, swap = ring.basis
    assert ring.member_from_matrix([[1, 1], [1, 1]]) == one + swap
    assert ring.member_from_matrix((one + swap).lift()) == one + swap
    with pytest.raises(ValueError, match="not in the ring"):
        ring.member_from_matrix([[1, 1], [0, 1]])
    with pytest.raises(ValueError, match="lifts to a 2x2 matrix"):
        ring.member_from_matrix(np.eye(3, dtype=int))
    with pytest.raises(ValueError, match="must be over GF"):
        ring.member_from_matrix(galois.GF(3)([[1, 1], [1, 1]]))


def test_members() -> None:
    """Terms of ring members are indexed by basis labels."""
    ring = abstract.MatrixRing(np.array([[0, 1], [1, 0]]), field=3)
    assert abstract.RingMember(ring, (2, 1)) == 2 * ring.basis[1]
    assert abstract.RingMember(ring, (2, 1)).to_vector().tolist() == [0, 2]
    assert abstract.RingMember(ring, (2, np.int64(1))) == abstract.RingMember(ring, (2, 1))
    for label in [-1, 2, 0.5]:
        with pytest.raises(ValueError, match="Invalid basis label"):
            abstract.RingMember(ring, (1, label))
        with pytest.raises(ValueError, match="Invalid basis label"):
            ring.lift(label)
        with pytest.raises(ValueError, match="Invalid basis label"):
            ring.regular_lift(label)


def test_read_only_lifts() -> None:
    """The matrices of a ring cannot be modified through its lifts."""
    ring = abstract.MatrixRing(np.array([[0, 1], [1, 0]]))
    for right in [False, True]:
        with pytest.raises(ValueError, match="read-only"):
            ring.lift(1, right=right)[0, 0] = 1
        with pytest.raises(ValueError, match="read-only"):
            ring.regular_lift(1, right=right)[0, 0] = 1
